/**
 * QuizLens AI - Options Page Script
 */

import { DEFAULT_SETTINGS } from '../shared/constants';
import { ExtensionSettings } from '../shared/types';

document.addEventListener('DOMContentLoaded', () => {
  const backendUrlInput = document.getElementById('backendUrl') as HTMLInputElement;
  const debounceMsInput = document.getElementById('debounceMs') as HTMLInputElement;
  const autoCopyInput = document.getElementById('autoCopy') as HTMLInputElement;

  const geminiModelSelect = document.getElementById('geminiModel') as HTMLSelectElement;
  const geminiApiKeyInput = document.getElementById('geminiApiKey') as HTMLInputElement;

  const groqModelSelect = document.getElementById('groqModel') as HTMLSelectElement;
  const groqApiKeyInput = document.getElementById('groqApiKey') as HTMLInputElement;

  const openrouterModelSelect = document.getElementById('openrouterModel') as HTMLSelectElement;
  const openrouterApiKeyInput = document.getElementById('openrouterApiKey') as HTMLInputElement;

  const saveBtn = document.getElementById('saveOptionsBtn') as HTMLButtonElement;
  const resetBtn = document.getElementById('resetBtn') as HTMLButtonElement;
  const saveStatus = document.getElementById('saveStatus') as HTMLSpanElement;

  function populateUI(settings: ExtensionSettings) {
    backendUrlInput.value = settings.backendUrl;
    debounceMsInput.value = String(settings.debounceMs || 400);
    autoCopyInput.checked = settings.autoCopy;

    geminiModelSelect.value = settings.geminiModel || 'gemini-1.5-flash';
    geminiApiKeyInput.value = settings.geminiApiKey || '';

    groqModelSelect.value = settings.groqModel || 'llama-3.3-70b-versatile';
    groqApiKeyInput.value = settings.groqApiKey || '';

    openrouterModelSelect.value = settings.openrouterModel || 'meta-llama/llama-3.3-70b-instruct:free';
    openrouterApiKeyInput.value = settings.openrouterApiKey || '';
  }

  // Load current settings
  chrome.runtime.sendMessage({ type: 'GET_SETTINGS' }, (res) => {
    if (res?.success && res.data) {
      populateUI(res.data);
    }
  });

  // Save changes
  saveBtn.addEventListener('click', () => {
    const updated: Partial<ExtensionSettings> = {
      backendUrl: backendUrlInput.value.trim() || DEFAULT_SETTINGS.backendUrl,
      debounceMs: Math.max(100, Math.min(3000, parseInt(debounceMsInput.value, 10) || 400)),
      autoCopy: autoCopyInput.checked,
      geminiModel: geminiModelSelect.value,
      geminiApiKey: geminiApiKeyInput.value.trim(),
      groqModel: groqModelSelect.value,
      groqApiKey: groqApiKeyInput.value.trim(),
      openrouterModel: openrouterModelSelect.value,
      openrouterApiKey: openrouterApiKeyInput.value.trim()
    };

    chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', payload: updated }, (res) => {
      if (res?.success) {
        saveStatus.textContent = 'Đã lưu thành công!';
        setTimeout(() => {
          saveStatus.textContent = '';
        }, 2500);
      }
    });
  });

  // Reset to defaults
  resetBtn.addEventListener('click', () => {
    if (confirm('Bạn có chắc chắn muốn khôi phục toàn bộ cài đặt về mặc định?')) {
      chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', payload: DEFAULT_SETTINGS }, (res) => {
        if (res?.success) {
          populateUI(DEFAULT_SETTINGS);
          saveStatus.textContent = 'Đã đặt lại về mặc định!';
          setTimeout(() => {
            saveStatus.textContent = '';
          }, 2500);
        }
      });
    }
  });
});

